import {fresh,apply,encounters,routes} from './engine.js';
const $=id=>document.getElementById(id);let state=fresh(),localServer=false,socket=null,demoCount=0;const overlay=location.pathname==='/overlay'||new URLSearchParams(location.search).has('overlay');if(overlay)document.body.classList.add('overlay');
const bus=new BroadcastChannel('chatquest');bus.onmessage=e=>{if(e.data.request){if(!overlay)bus.postMessage({state});}else if(e.data.state){state=e.data.state;render();}};bus.postMessage({request:true});
try{const r=await fetch('/api/state');if(r.ok&&r.headers.get('content-type')?.includes('application/json')){state=await r.json();localServer=true;const events=new EventSource('/api/events');events.onmessage=e=>{state=JSON.parse(e.data);render();};events.onerror=()=>{$('mode').textContent='Server connection interrupted';};$('mode').textContent='Local studio · OBS ready';}}catch{}
async function dispatch(action){if(overlay)return;if(localServer){try{const r=await fetch('/api/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(action)});if(!r.ok)throw Error();state=await r.json();}catch{$('status').textContent='SERVER UNAVAILABLE';return;}}else{state=apply(state,action);bus.postMessage({state});}render();}
function render(){const e=encounters[state.phase],players=Object.entries(state.players);$('count').textContent=players.length;$('chapter').textContent=`0${state.phase+1} / 03`;$('chapterNum').textContent=state.phase+1;$('xp').textContent=players.reduce((n,[,p])=>n+p.score,0);$('kind').textContent=e.kind;$('title').textContent=e.name;$('description').textContent=e.description;$('command').textContent=e.command;$('monster').textContent=e.icon;$('timer').textContent=`${String(Math.floor(state.left/60)).padStart(2,'0')}:${String(state.left%60).padStart(2,'0')}`;$('outcome').textContent=state.outcome;$('status').textContent=state.running?'● ENCOUNTER LIVE':state.outcome?'● ENCOUNTER ENDED':'● READY TO START';$('start').textContent=state.started?'▶ Resume encounter':'▶ Start encounter';$('start').disabled=state.running||!!state.outcome;$('pause').disabled=!state.running;$('next').disabled=state.phase===2;$('hp').style.width=(state.hp/state.maxHp*100)+'%';document.querySelector('.health').hidden=state.phase!==2;
document.querySelector('.arena').classList.toggle('won',state.result==='victory');
document.querySelector('.arena').classList.toggle('forest',state.route==='forest'&&state.phase===2);
for(let i=0;i<3;i++)$('step'+i).classList.toggle('active',state.phase===i);
$('finishVote').hidden=state.phase!==1;$('finishVote').disabled=!state.started||!!state.result;
$('retry').disabled=!state.started&&!state.result;
$('route-note').hidden=!state.route;$('route-note').textContent=state.route?routes[state.route].name+' · '+routes[state.route].description:'';
if(state.phase===2){$('description').textContent=routes[state.route||'bridge'].description;$('command').textContent='!attack · '+routes[state.route||'bridge'].power;$('monster').textContent=state.result==='victory'?'✦':'♜';}
$('vote-results').hidden=state.phase!==1;
if(state.phase===1){const votes=Object.values(state.votes),bridge=votes.filter(v=>v==='bridge').length,forest=votes.filter(v=>v==='forest').length,total=bridge+forest;$('vote-results').replaceChildren();for(const [label,n] of [['Crystal bridge',bridge],['Shadow forest',forest]]){const row=document.createElement('div');row.className='vote-row';const text=document.createElement('span');text.textContent=label+' · '+n;const meter=document.createElement('meter');meter.min=0;meter.max=Math.max(1,total);meter.value=n;meter.setAttribute('aria-label',label+' votes');row.append(text,meter);$('vote-results').append(row);}}
$('victory').hidden=state.result!=='victory';
if(state.result==='victory'){const sun=players.filter(([,p])=>p.team==='sun').reduce((n,[,p])=>n+p.score,0),moon=players.filter(([,p])=>p.team==='moon').reduce((n,[,p])=>n+p.score,0);$('victory-title').textContent=sun===moon?'Two guilds. One legendary victory.':(sun>moon?'Sun':'Moon')+' guild leads the heroes!';$('victory-credits').textContent=players.length+' heroes · '+(sun+moon)+' community XP · '+state.left+' seconds to spare. Starring '+players.map(([name])=>name).join(', ');}

for(const team of ['sun','moon']){const members=players.filter(([,p])=>p.team===team);$(team).textContent=`${members.length} heroes · ${members.reduce((n,[,p])=>n+p.score,0)} XP`;}
$('messages').replaceChildren(...state.log.slice(0,20).reverse().map(m=>{const row=document.createElement('div');row.className='message';const name=document.createElement('b');name.textContent=m.user;row.append(name,document.createTextNode(m.message));return row;}));$('messages').scrollTop=$('messages').scrollHeight;
const leaders=players.sort((a,b)=>b[1].score-a[1].score).slice(0,5);$('leaders').replaceChildren(...leaders.map(([name,p],i)=>{const row=document.createElement('div');row.className='hero';row.textContent=`${i+1}. ${name} · ${p.team==='sun'?'☀':'☾'}`;const xp=document.createElement('span');xp.textContent=p.score+' XP';row.append(xp);return row;}));if(!leaders.length)$('leaders').textContent='Your community’s story starts with !join.';
if(state.phase===1&&Object.keys(state.votes).length){const v=Object.values(state.votes);$('description').textContent=`Crystal bridge: ${v.filter(x=>x==='bridge').length} votes · Shadow forest: ${v.filter(x=>x==='forest').length} votes`;}}
for(const type of ['start','pause','next','retry','finishVote'])$(type).onclick=()=>dispatch({type});$('reset').onclick=()=>{if(confirm('Reset the campaign and clear all heroes and scores?'))dispatch({type:'reset'});};$('demo').onclick=()=>dispatch({type:'chat',user:'Hero_'+(++demoCount)+'_'+Math.floor(Math.random()*1000),message:'!join '+(demoCount%2?'sun':'moon')});$('chat').onsubmit=e=>{e.preventDefault();dispatch({type:'chat',user:$('username').value.trim()||'You',message:$('message').value});$('message').value='';};$('settings').onclick=()=>$('connection').showModal();$('guide').onclick=()=>$('instructions').showModal();$('room').onclick=()=>window.scrollTo({top:0,behavior:'smooth'});$('overlay').onclick=()=>window.open(localServer?'/overlay':'/?overlay=1','chatquest-overlay');
for(const button of document.querySelectorAll('[data-command]'))button.onclick=()=>dispatch({type:'chat',user:$('username').value.trim()||'You',message:button.dataset.command});
let reconnectTimer=null,manual=false,config=null;function status(t){$('connection-status').textContent=t;$('mode').textContent=t;}
function connect(){clearTimeout(reconnectTimer);if(socket){socket.onclose=null;socket.close();}socket=new WebSocket('wss://irc-ws.chat.twitch.tv:443');socket.onopen=()=>{status('Authenticating with Twitch…');socket.send('PASS oauth:'+config.token+'\r\n');socket.send('NICK '+config.bot+'\r\n');};let buffer='';socket.onmessage=e=>{buffer+=e.data;const lines=buffer.split('\r\n');buffer=lines.pop();for(const line of lines){if(line.startsWith('PING '))socket.send('PONG '+line.slice(5)+'\r\n');if(/ 001 /.test(line))socket.send('JOIN #'+config.channel+'\r\n');if(line.includes(' 366 ')){status('Connected to #'+config.channel);$('settings').textContent='● Twitch connected';}if(/authentication failed|Login unsuccessful|Improperly formatted auth/i.test(line)){manual=true;status('Authentication failed. Check your username and token.');socket.close();}const match=line.match(/^:([^!]+)![^ ]+ PRIVMSG #[^ ]+ :(.*)$/);if(match)dispatch({type:'chat',user:match[1],message:match[2]});if(line.startsWith('RECONNECT'))socket.close();}};socket.onerror=()=>status('Twitch connection error');socket.onclose=()=>{if(!manual){status('Twitch disconnected · retrying in 5 seconds');reconnectTimer=setTimeout(connect,5000);}};}
$('connect').onsubmit=e=>{e.preventDefault();config={channel:$('channel').value.toLowerCase(),bot:$('bot').value.toLowerCase(),token:$('token').value.replace(/^oauth:/,'').trim()};$('token').value='';manual=false;connect();};$('disconnect').onclick=()=>{manual=true;clearTimeout(reconnectTimer);socket?.close();config=null;status('Twitch disconnected');$('settings').textContent='⚙ Connect Twitch';};
let clockLeader=false;
if(!overlay&&!localServer&&navigator.locks){navigator.locks.request('chatquest-clock',async()=>{clockLeader=true;bus.postMessage({request:true});await new Promise(()=>{});});}
if(!overlay)setInterval(()=>{if(!localServer&&state.running&&(clockLeader||!navigator.locks))dispatch({type:'tick'});},1000);render();
